// Modern Animation Hook
const useModernAnimations = () => {
  const titleFade = useRef(new Animated.Value(0)).current;
  const titleSlide = useRef(new Animated.Value(-30)).current;
  const descriptionFade = useRef(new Animated.Value(0)).current;
  const descriptionSlide = useRef(new Animated.Value(20)).current;
  const buttonsFade = useRef(new Animated.Value(0)).current;
  const buttonsSlide = useRef(new Animated.Value(30)).current;

  useEffect(() => {
    const sequence = Animated.sequence([
      // Prima il titolo con effetto drammatico
      Animated.parallel([
        Animated.timing(titleFade, {
          toValue: 1,
          duration: 1000,
          useNativeDriver: true,
        }),
        Animated.spring(titleSlide, {
          toValue: 0,
          useNativeDriver: true,
          tension: 40,
          friction: 8,
        }),
      ]),
      // Poi la descrizione
      Animated.delay(300),
      Animated.parallel([
        Animated.timing(descriptionFade, {
          toValue: 1,
          duration: 800,
          useNativeDriver: true,
        }),
        Animated.spring(descriptionSlide, {
          toValue: 0,
          useNativeDriver: true,
          tension: 50,
          friction: 8,
        }),
      ]),
      // Infine i bottoni
      Animated.delay(200),
      Animated.parallel([
        Animated.timing(buttonsFade, {
          toValue: 1,
          duration: 600,
          useNativeDriver: true,
        }),
        Animated.spring(buttonsSlide, {
          toValue: 0,
          useNativeDriver: true,
          tension: 60,
          friction: 8,
        }),
      ]),
    ]);

    sequence.start();

    return () => {
      sequence.stop();
    };
  }, [
    titleFade,
    titleSlide,
    descriptionFade,
    descriptionSlide,
    buttonsFade,
    buttonsSlide,
  ]);

  return {
    titleFade,
    titleSlide,
    descriptionFade,
    descriptionSlide,
    buttonsFade,
    buttonsSlide,
  };
};

